// swift-tools-version:5.9
// Flint Design System tokens for SwiftUI. Source: tokens.json plus brands/ and platforms/ios.json;
// the Swift files under dist/ are generated by `npm run build`.
//
// One product per brand (ASDS-86). Add the one your app ships and `import` it; every brand
